using System;using System.IO;using System.Linq;using System.Reflection;using System.Security.Cryptography;using SoulsFormats;class BloodborneTextureTests{static void Check(bool x,string s){if(!x)throw new Exception(s);Console.WriteLine("PASS "+s);}static int Main(string[] a){try{var asm=Assembly.LoadFrom(a[0]);var type=asm.GetType("MySFformat.TpfTextureDecoder");Check(type!=null,"platform-aware TPF decoder exists");var decode=type.GetMethod("GetDdsBytes");foreach(var path in a.Skip(1)){byte[] original=File.ReadAllBytes(path);var b=BND4.Read(path);int count=0;foreach(var f in b.Files.Where(x=>x.Name.EndsWith(".tpf",StringComparison.OrdinalIgnoreCase))){var tpf=TPF.Read(f.Bytes);foreach(var t in tpf.Textures){byte[] before=(byte[])t.Bytes.Clone();byte[] dds=(byte[])decode.Invoke(null,new object[]{t});Check(dds.Take(4).SequenceEqual(new byte[]{68,68,83,32}),"DDS header "+t.Name);using(var stream=new MemoryStream(dds))using(var image=Pfim.Pfim.FromStream(stream)){Check(image.Width>0&&image.Height>0&&image.Data.Length>0,"decoded pixels "+t.Name+" "+image.Width+"x"+image.Height);}Check(before.SequenceEqual(t.Bytes),"source texture bytes unchanged");var pc=new TPF.Texture(){Name="pc",Bytes=dds};Check(((byte[])decode.Invoke(null,new object[]{pc})).SequenceEqual(dds),"PC DDS unchanged");count++;}}Check(count>0,"textures found in "+path);Check(original.SequenceEqual(File.ReadAllBytes(path)),"source DCX unchanged");Console.WriteLine("TEXTURES="+count);}return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}}